-- Apply to the LOCAL test database first, after Server_Scheduling_Invoice_Release.sql.
-- No invoices, payments, emails, or historical class counts are generated by this script.
DECLARE @ExpectedDatabase sysname = N'CHANGE_ME';
IF @ExpectedDatabase = N'CHANGE_ME' OR DB_NAME() <> @ExpectedDatabase
    THROW 51000, 'Set @ExpectedDatabase to the exact API database name before running this script.', 1;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID(N'dbo.StudentPaymentPlan', N'U') IS NULL
    THROW 51000, 'Deploy the existing scheduling/invoice schema first.', 1;
IF OBJECT_ID(N'dbo.PrepaidClassCharge', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.PrepaidClassCharge
    (
        Id uniqueidentifier NOT NULL CONSTRAINT PK_PrepaidClassCharge PRIMARY KEY,
        StudentPaymentPlanId uniqueidentifier NOT NULL,
        ScheduleDetailsId uniqueidentifier NOT NULL,
        StudentInvoiceId bigint NOT NULL,
        Amount decimal(18,2) NOT NULL,
        CreatedDate datetime2 NOT NULL,
        CONSTRAINT FK_PrepaidClassCharge_Plan FOREIGN KEY (StudentPaymentPlanId) REFERENCES dbo.StudentPaymentPlan(Id),
        CONSTRAINT FK_PrepaidClassCharge_Class FOREIGN KEY (ScheduleDetailsId) REFERENCES dbo.ScheduleDetails(ScheduleDetailsId),
        CONSTRAINT FK_PrepaidClassCharge_Invoice FOREIGN KEY (StudentInvoiceId) REFERENCES dbo.StudentInvoice(Id),
        CONSTRAINT CK_PrepaidClassCharge_Amount CHECK (Amount >= 0)
    );
    -- Global per-class uniqueness also prevents billing the same class under a replacement plan.
    CREATE UNIQUE INDEX UX_PrepaidClassCharge_Class ON dbo.PrepaidClassCharge(ScheduleDetailsId);
    CREATE INDEX IX_PrepaidClassCharge_Plan ON dbo.PrepaidClassCharge(StudentPaymentPlanId) INCLUDE (Amount, StudentInvoiceId);
END;
COMMIT;

-- Read-only readiness report. Existing issued plans with no frozen class count require
-- Accounts review against their original invoice; do NOT infer from today's expanded schedule.
SELECT Id, SalesDetailsId, StudentId, UpfrontInvoiceNumber, TotalClasses
FROM dbo.StudentPaymentPlan
WHERE IsActive = 1 AND UpfrontInvoiceNumber IS NOT NULL
  AND (TotalClasses IS NULL OR TotalClasses <= 0);
